theme_set(theme_classic(base_size=11,base_family='Arial')+theme(plot.title=element_text(size=13,face='bold'),plot.subtitle=element_text(size=10,color='#444444'),axis.title=element_text(size=11),axis.text=element_text(color='#202020'),legend.title=element_text(size=10),legend.position='bottom',strip.background=element_blank(),strip.text=element_text(face='bold',size=10),plot.margin=margin(8,12,8,8)))
saveplot<-function(p,n,w=8,h=5){ggsave(file.path(fig,paste0(n,'.png')),p,width=w,height=h,dpi=320,bg='white',device=ragg::agg_png);ggsave(file.path(fig,paste0(n,'.pdf')),p,width=w,height=h,device=cairo_pdf,bg='white')}
fmt<-function(q)ifelse(q<.001,formatC(q,format='e',digits=1),formatC(q,format='f',digits=3))
star<-function(q)ifelse(q<.001,'***',ifelse(q<.01,'**',ifelse(q<.05,'*',ifelse(q<.1,'\u2020','ns'))))
canon<-function(n){n<-sub(' - animal$','',n);n}
key<-function(n)gsub('[^a-z0-9]','',tolower(canon(n)))
colors<-c('T-lineage candidate'='#3D5A80','B cell'='#0072B2','Myeloid'='#E69F00','pDC'='#CC79A7','Erythroid'='#D55E00','Cytotoxic T/NK'='#009E73')
u<-rd('annotation_umap');u$reviewed_cell_type<-factor(u$reviewed_cell_type,levels=names(colors))
cent<-u |> group_by(cluster_res0.6) |> summarise(UMAP1=median(UMAP1),UMAP2=median(UMAP2),.groups='drop')
p<-ggplot(u,aes(UMAP1,UMAP2))+geom_point(aes(color=reviewed_cell_type),size=.22,alpha=.65,stroke=0)+geom_label_repel(data=cent,aes(label=cluster_res0.6),size=2.6,fill='white',label.size=.15,seed=4,max.overlaps=50,min.segment.length=0)+scale_color_manual(values=colors,name=NULL,guide=guide_legend(override.aes=list(size=2.5,alpha=1),nrow=2))+coord_equal()+labs(title='Cell lineage annotation',subtitle='13,953 cells; numbers indicate clusters',x='UMAP 1',y='UMAP 2')+theme(axis.text=element_blank(),axis.ticks=element_blank())
