cts<-rd('selection_cell_counts');cts$sample<-factor(paste(cts$patient_pair,ifelse(cts$condition_simple=='diagnosis','Dx','Rel')),levels=c('P1 Dx','P1 Rel','P2 Dx','P2 Rel','P3 Dx','P3 Rel'))
lab<-c(global25='Global top 25%\noriginal definition',within15='Within-sample top 15%\nexploratory core',within25='Within-sample top 25%\nsensitivity',reference95='Reference q95\nabsolute cutoff')
