saveplot(p,'Fig02_paired_sample_cell_counts',8,4.1);wr(cts,'Table03_cell_selection_counts')
sc<-rd('KEGG_within15');original<-rd('KEGG_global25');bulk<-rd('KEGG_bulk')
readable<-function(x)x |> transmute(Pathway=canon(pathway_name),NES=NES,P_value=pval,FDR=padj,Direction=direction,Genes_tested=size,Leading_edge_genes=leadingEdge) |> arrange(FDR)
wr(readable(sc),'Table04_scRNAseq_all_KEGG_within15');wr(readable(bulk),'Table05_bulk_STAT5B_all_KEGG');wr(readable(original),'TableS01_scRNAseq_all_KEGG_global25')
overview<-function(x,title,subtitle,nshow=15){
  z<-x |> filter(padj<.1) |> group_by(direction) |> arrange(padj,.by_group=TRUE) |> slice_head(n=nshow) |> ungroup();z$label<-canon(z$pathway_name);z$label<-factor(z$label,levels=z$label[order(z$NES)])
  cnt<-x |> filter(padj<.1) |> count(direction);note<-paste(paste0(cnt$direction,': ',cnt$n),collapse='; ')
  ggplot(z,aes(NES,label))+geom_vline(xintercept=0,color='#8A8A8A',linewidth=.35)+geom_segment(aes(x=0,xend=NES,yend=label),color='#CCD3DA',linewidth=.6)+geom_point(aes(size=size,color=-log10(padj)),alpha=1)+scale_color_gradient(low='#7099B5',high='#4C075F',name=expression(-log[10](FDR)))+scale_size_continuous(range=c(2,5),name='Genes tested')+labs(title=title,subtitle=paste0(subtitle,'\n',note,' at FDR < 0.10; up to ',nshow,' per direction, ranked by FDR'),x='Normalized enrichment score (NES)',y=NULL)+theme(axis.text.y=element_text(size=9))
}
saveplot(overview(sc,'Relapse scRNA-seq: KEGG enrichment','Within-sample top 15%; paired relapse vs diagnosis'),'Fig03_scRNAseq_all_pathway_overview',9.5,7.8)
saveplot(overview(bulk,'STAT5B N642H bulk RNA-seq: KEGG enrichment','N642H vs control; independent 3 vs 3 samples'),'Fig04_bulk_all_pathway_overview',9.5,8.4)
