cross<-function(x,id){a<-x |> transmute(key=key(pathway_name),Pathway=canon(pathway_name),sc_NES=NES,sc_FDR=padj,sc_P=pval,sc_genes=size);b<-bulk |> transmute(key=key(pathway_name),bulk_Pathway=canon(pathway_name),bulk_NES=NES,bulk_FDR=padj,bulk_P=pval,bulk_genes=size);stopifnot(!anyDuplicated(a$key),!anyDuplicated(b$key));full_join(a,b,by='key') |> mutate(Pathway=coalesce(Pathway,bulk_Pathway),analysis=id,tested_in_both=!is.na(sc_FDR)&!is.na(bulk_FDR),sc_significant=!is.na(sc_FDR)&sc_FDR<.1,bulk_significant=!is.na(bulk_FDR)&bulk_FDR<.1,same_direction=tested_in_both & sign(sc_NES)==sign(bulk_NES),shared_FDR010=sc_significant&bulk_significant&same_direction) |> select(-bulk_Pathway) }
cx<-bind_rows(cross(sc,'within15'),cross(original,'global25'));wr(cx,'Table06_cross_dataset_pathway_membership');wr(cx |> filter(shared_FDR010) |> arrange(analysis,pmax(sc_FDR,bulk_FDR)),'Table07_same_direction_intersection')
venn<-function(x,id,dir){
  z<-x |> filter(analysis==id,tested_in_both);a<-z$key[z$sc_significant & if(dir=='Up')z$sc_NES>0 else z$sc_NES<0];b<-z$key[z$bulk_significant & if(dir=='Up')z$bulk_NES>0 else z$bulk_NES<0]
  theta<-seq(0,2*pi,length.out=301);cir<-bind_rows(data.frame(x=.85+cos(theta),y=sin(theta),Dataset='scRNA-seq'),data.frame(x=2.05+cos(theta),y=sin(theta),Dataset='Bulk'))
  txt<-data.frame(x=c(.4,1.45,2.5),y=0,label=c(length(setdiff(a,b)),length(intersect(a,b)),length(setdiff(b,a))))
  ggplot(cir,aes(x,y,group=Dataset))+geom_polygon(aes(fill=Dataset),alpha=.18,color=NA)+geom_path(aes(color=Dataset),linewidth=.65)+geom_text(data=txt,aes(x,y,label=label),inherit.aes=FALSE,size=5.5,fontface='bold')+annotate('text',x=c(.55,2.4),y=1.25,label=c('scRNA-seq','Bulk'),size=3.6,color=c('#0072B2','#D55E00'))+scale_fill_manual(values=c('scRNA-seq'='#0072B2',Bulk='#D55E00'))+scale_color_manual(values=c('scRNA-seq'='#0072B2',Bulk='#D55E00'))+coord_equal(xlim=c(-.3,3.25),ylim=c(-1.2,1.55))+theme_void(base_family='Arial')+theme(legend.position='none',plot.title=element_text(size=12,face='bold',hjust=.5),plot.subtitle=element_text(size=9,hjust=.5))+labs(title=paste0(dir,'-enriched'),subtitle=paste0(nrow(z),' common tested pathways'))
}
p<-(venn(cx,'within15','Up')+venn(cx,'within15','Down')) / (venn(cx,'global25','Up')+venn(cx,'global25','Down'))+plot_annotation(title='Direction-matched KEGG overlap',subtitle='Top row: within-sample top 15% (exploratory); bottom row: original global top 25%\nFDR < 0.10 in each full collection; circles are not proportional to set size',tag_levels='A')
saveplot(p,'Fig05_direction_matched_intersection',9,7.6)
shared<-cx |> filter(analysis=='within15',shared_FDR010) |> arrange(desc(pmin(sc_NES,bulk_NES)))
z<-bind_rows(shared |> transmute(Pathway,Dataset='Relapse\nscRNA-seq',NES=sc_NES,FDR=sc_FDR),shared |> transmute(Pathway,Dataset='STAT5B N642H\nbulk RNA-seq',NES=bulk_NES,FDR=bulk_FDR));z$Pathway<-factor(z$Pathway,levels=rev(shared$Pathway));z$Dataset<-factor(z$Dataset,levels=c('Relapse\nscRNA-seq','STAT5B N642H\nbulk RNA-seq'))
p<-ggplot(z,aes(Dataset,Pathway,fill=NES))+geom_tile(color='white',linewidth=.7)+geom_text(aes(label=paste0(sprintf('%.2f',NES),' ',star(FDR))),size=3.2)+scale_fill_gradient2(low='#2166AC',mid='white',high='#B2182B',midpoint=0,limits=c(-3,3),oob=scales::squish,name='NES')+labs(title='Shared KEGG pathways',subtitle='Within-sample top 15%; both datasets FDR < 0.10',x=NULL,y=NULL,caption='* FDR < 0.05; ** < 0.01; *** < 0.001; \u2020 < 0.10\nPathway names do not imply the corresponding disease is present.')+theme(axis.line=element_blank(),axis.ticks=element_blank(),axis.text.y=element_text(size=9),plot.caption=element_text(hjust=0,size=9))
saveplot(p,'Fig06_shared_pathways_NES_heatmap',8,max(5,.24*nrow(shared)+2.1))
